import javax.swing.*;import java.awt.*;
public class Main {public static void main(String[]a){SwingUtilities.invokeLater(()->{JFrame f=new JFrame("Appointment Booking");JTextField patient=new JTextField();JComboBox<String> dept=new JComboBox<>(new String[]{"Cardiology","Orthopaedics"}),doctor=new JComboBox<>(),slot=new JComboBox<>(new String[]{"10:00","11:00","12:00"});dept.addActionListener(e->{doctor.removeAllItems();if(dept.getSelectedIndex()==0){doctor.addItem("Dr Rao");doctor.addItem("Dr Kumar");}else doctor.addItem("Dr Devi");});dept.setSelectedIndex(0);JButton book=new JButton("Book");JLabel status=new JLabel("Ready");book.addActionListener(e->{if(patient.getText().isBlank())status.setText("Enter patient ID");else status.setText("Booked: "+patient.getText()+", "+doctor.getSelectedItem()+", "+slot.getSelectedItem());});f.setLayout(new GridLayout(0,2,6,6));f.add(new JLabel("Patient ID"));f.add(patient);f.add(new JLabel("Department"));f.add(dept);f.add(new JLabel("Doctor"));f.add(doctor);f.add(new JLabel("Time"));f.add(slot);f.add(book);f.add(status);f.pack();f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);f.setVisible(true);});}}
